<script setup>
import { ref } from 'vue';
import { libraryRequest } from '../lib/library-client.js';
const props=defineProps({bookId:{type:String,required:true}}),emit=defineEmits(['imported']);
const files=ref([]),session=ref(null),choices=ref({}),pending=ref(false),error=ref(''),message=ref('');
function encode(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});}
async function preview(){error.value='';message.value='';if(!files.value.length||files.value.length>3||files.value.reduce((n,f)=>n+f.size,0)>5*1024*1024){error.value='Chọn tối đa3 MP3, tổng5MiB.';return;}pending.value=true;try{const inputs=[];for(const f of files.value)inputs.push({name:f.name,content_base64:await encode(f)});session.value=await libraryRequest(`/${props.bookId}/audio-imports`,{files:inputs});choices.value=Object.fromEntries(session.value.items.map(i=>[i.id,i.valid?i.suggested_chapter_id||'':'']));}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function confirm(){pending.value=true;error.value='';try{const items=Object.entries(choices.value).filter(([,id])=>id).map(([item_id,chapter_id])=>({item_id,chapter_id}));if(!items.length)throw new Error('Chọn chương cho ít nhất một MP3 hợp lệ.');const result=await libraryRequest(`/${props.bookId}/audio-imports/${session.value.id}/confirm`,{items});session.value.status='confirmed';message.value=`Đã xác nhận ${result.outcomes.length} audio nhập trước.`;emit('imported');}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function cancel(){pending.value=true;try{await libraryRequest(`/${props.bookId}/audio-imports/${session.value.id}/cancel`,{});session.value=null;}catch(e){error.value=e.message;}finally{pending.value=false;}}
</script>
<template>
  <section class="mt-5 rounded-xl border border-line bg-surface p-5" aria-labelledby="audio-import-title">
    <h2 id="audio-import-title" class="text-sm font-semibold">Nhập MP3 đã có</h2><p class="mt-2 text-xs leading-5 text-muted">Tối đa3 file, tổng5MiB mỗi phiên. Xác minh file bằng ffprobe rồi xác nhận ánh xạ vào chương. Audio nhập trước chưa được xác minh đọc khớp từng từ.</p>
    <div class="mt-4 flex flex-wrap items-end gap-3"><label for="mp3-files" class="grid min-w-0 gap-2 text-xs">File MP3<input id="mp3-files" type="file" accept=".mp3,audio/mpeg" multiple :disabled="pending||session?.status==='preview'" class="max-w-full rounded border border-line p-2" @change="files=[...$event.target.files]" /></label><button id="preview-mp3" :disabled="pending||!files.length||session?.status==='preview'" class="rounded-lg border border-line px-3 py-2 text-sm disabled:opacity-50" @click="preview">Xem trước MP3</button></div>
    <p v-if="error" id="audio-import-error" role="alert" class="mt-3 text-sm">{{error}}</p><p v-if="pending" role="status" class="mt-3 text-xs">Đang kiểm tra…</p><p v-if="message" id="audio-import-message" role="status" class="mt-3 text-xs text-brand">{{message}}</p>
    <div v-if="session?.status==='preview'" id="audio-preview" class="mt-4"><div v-for="item in session.items" :key="item.id" :data-audio-name="item.name" class="border-t border-line py-3"><p class="text-sm font-medium break-all">{{item.name}}</p><p class="mt-2 text-xs text-muted">{{item.message}} {{item.duration?`${item.duration.toFixed(2)} giây`:''}}</p><label class="mt-3 grid gap-2 text-xs">Chương sẽ nhận audio<select v-model="choices[item.id]" :disabled="pending||!item.valid" :aria-label="`Ánh xạ ${item.name}`" class="rounded border border-line bg-canvas p-2"><option value="">Bỏ qua / chưa chọn chương</option><option v-for="chapter in session.chapters" :key="chapter.id" :value="chapter.id">{{chapter.number}} · {{chapter.title}}</option></select></label></div><div class="mt-3 flex flex-wrap gap-3"><button id="confirm-mp3" :disabled="pending" class="rounded-lg bg-brand px-4 py-2 text-sm text-brand-ink" @click="confirm">Xác nhận ánh xạ audio</button><button :disabled="pending" class="text-xs text-brand underline" @click="cancel">Hủy phiên MP3</button></div></div>
  </section>
</template>
